function layout(){if(!canOpenPage(page)){page="dashboard";selected=null;} let [title,sub]=pageTitle();$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">L</div><div><div class="brand-name">LANGGENG</div><div class="brand-sub">Institutional Memory System</div></div></div><div><nav class="nav">${navItems.filter(([id])=>canOpenPage(id)).map(([id,ico,name])=>`<button data-page="${id}" class="${page===id?'active':''}"><span class="ico">${ico}</span>${name}${id==='verify'&&db.records.filter(r=>r.status==='Menunggu Verifikasi').length?`<span class="badge badge-amber" style="margin-left:auto;padding:3px 7px">${db.records.filter(r=>r.status==='Menunggu Verifikasi').length}</span>`:''}</button>`).join('')}</nav></div><div class="side-bottom"><div class="profile"><div class="avatar">${role==='Dosen'?'DR':role==='Pimpinan'?'PD':role==='Mahasiswa'?'M':'AR'}</div><div><div class="profile-name">${role==='Arsiparis'?'Siti Rahmawati':role==='Pimpinan'?'Dr. R. Pratama':role==='Dosen'?'Dr. Rani Prameswari':role==='Mahasiswa'?'Nadia Putri':'Admin Unit'}</div><div class="profile-role">${esc(role)}</div></div></div><button class="logout" data-action="logout">Keluar</button></div></aside><div class="mobile-overlay" id="overlay"></div><main class="main"><header class="topbar"><button class="hamburger" id="hamb">☰</button><div class="top-search"><span class="search-icon">⌕</span><input id="globalSearch" placeholder="Cari arsip, pengetahuan, atau kegiatan…" value="${esc(query)}" aria-label="Pencarian terintegrasi"></div><div class="top-actions"><span class="sim-label">${esc(role)}</span></div></header><div class="main-inner"><div class="page-head"><div><div class="eyebrow">Sekolah Vokasi Universitas Padjadjaran</div><h1 class="page-title">${title}</h1><p class="page-subtitle">${sub}</p></div>${page==='records'?`<div class="actions"><button class="btn btn-primary" data-action="new-record">＋ Tambah arsip</button></div>`:page==='knowledge'?`<div class="actions"><button class="btn btn-primary" data-action="new-knowledge">＋ Tambah pengetahuan</button></div>`:''}</div><div id="content"></div></div></main></div>`;$$('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;selected=null;query='';render()});$('#globalSearch').onkeydown=e=>{if(e.key==='Enter'){query=e.target.value;page='search';render()}};$('#globalSearch').oninput=e=>{query=e.target.value};$('#hamb').onclick=()=>{$('#sidebar').classList.add('open');$('#overlay').classList.add('show')};$('#overlay').onclick=()=>{$('#sidebar').classList.remove('open');$('#overlay').classList.remove('show')};$('#content').innerHTML=pages[page]();bind();}
const iconBox=(f='PDF')=>`<div class="file-icon">${esc(f)}</div>`;
function archiveStatusChart() {
  const statuses = [
    ['Terverifikasi', '#287154'],
    ['Menunggu Verifikasi', '#315f95'],
    ['Perlu Perbaikan', '#bb862a'],
    ['Draft', '#777b9a']
  ];
  const total = db.records.length;
  let offset = 0;
  const groups = statuses.map(([label, color]) => {
    const count = db.records.filter(record => record.status === label).length;
    const start = offset;
    offset += total ? count / total * 100 : 0;
    return {label, color, count, start, end: offset};
  });
  const segments = groups.filter(group => group.count).map(group =>
    `${group.color} ${group.start}% ${group.end}%`).join(', ');
  return `<section class="card section-card archive-chart">
    <h2 class="card-title">Status arsip digital</h2>
    <div class="archive-chart-body">
      <div class="archive-ring" style="background:${segments ? `conic-gradient(${segments})` : '#e7ebe7'}" aria-hidden="true">
        <div><strong>${total}</strong><span>Total arsip</span></div>
      </div>
      <dl class="archive-legend">${groups.map(group =>
        `<div><dt><span style="background:${group.color}"></span>${group.label}</dt><dd>${group.count}</dd></div>`).join('')}</dl>
    </div>
  </section>`;
}

const queuePages = {chart: 1, verify: 1};

function paginateQueue(items, key, limit) {
  const pages = Math.max(1, Math.ceil(items.length / limit));
  const current = Math.max(1, Math.min(queuePages[key], pages));
  queuePages[key] = current;
  const start = (current - 1) * limit;
  const controls = pages > 1 ? `<div class="queue-pagination">
    <span>Halaman ${current} dari ${pages} (${items.length} total)</span>
    <button class="btn btn-sm" data-action="queue-page" data-id="${key}" data-step="-1" ${current === 1 ? 'disabled' : ''}>Sebelumnya</button>
    <button class="btn btn-sm" data-action="queue-page" data-id="${key}" data-step="1" ${current === pages ? 'disabled' : ''}>Berikutnya</button>
  </div>` : '';
  return {items: items.slice(start, start + limit), controls};
}

function verificationChart() {
  if (!isVerifier()) return '';
  const pending = db.records.filter(record => record.status === 'Menunggu Verifikasi');
  const units = [...Map.groupBy(pending, record => record.unit)]
    .sort(([left, a], [right, b]) => b.length - a.length || left.localeCompare(right));
  const max = units[0]?.[1].length || 1;
  const visible = paginateQueue(units, 'chart', 5);
  return `<section class="card section-card backlog-chart">
    <h2 class="card-title">Antrean verifikasi per unit</h2>
    <p class="page-subtitle">Pilih unit untuk melihat arsip yang perlu diperiksa.</p>
    ${visible.items.map(([unit, records]) => `<button class="backlog-row" data-action="open-unit-queue" data-id="${esc(unit)}" aria-label="${esc(unit)}, ${records.length} arsip menunggu verifikasi">
      <span>${esc(unit)}</span><span class="backlog-track" aria-hidden="true"><span style="width:${records.length / max * 100}%"></span></span><strong>${records.length}</strong>
    </button>`).join('') || '<p class="page-subtitle">Tidak ada arsip menunggu verifikasi.</p>'}${visible.controls}
  </section>`;
}

