function recordTable(list){if(!list.length)return `<div class="empty"><div class="empty-icon">⌕</div><strong>Belum ada arsip yang cocok</strong><div>Coba ubah kata kunci atau filter.</div></div>`;return `<div class="card table-wrap"><table class="table"><thead><tr><th>Judul arsip</th><th>Jenis</th><th>Prodi / Unit</th><th>Tahun</th><th>Status</th><th></th></tr></thead><tbody>${list.map(r=>`<tr><td><div class="table-title">${esc(r.title)}</div><div class="table-sub"><span class="record-code">${esc(r.id)}</span><span class="meta-context">${esc(r.activity)}</span></div></td><td>${esc(r.kind)}</td><td>${esc(r.unit)}</td><td>${esc(r.year)}</td><td>${badge(r.status)}</td><td><button class="btn btn-sm" data-record="${r.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`}
function records(){if(selected){let r=db.records.find(x=>x.id===selected);if(r)return recordDetail(r)}let filtered=db.records.filter(r=>(filter==='Semua'||r.status===filter)&&(!query||Object.values(r).join(' ').toLowerCase().includes(query.toLowerCase())));return `<div class="toolbar"><div class="field-search"><span>⌕</span><input id="recSearch" placeholder="Cari judul, unit, kegiatan…" value="${esc(query)}"></div><select class="select" id="recFilter"><option>Semua</option>${['Terverifikasi','Menunggu Verifikasi','Perlu Perbaikan','Draft'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><span class="sim-label">${filtered.length} arsip</span></div><div class="tabs">${['Semua','Digital','Fisik'].map(x=>`<button class="tab ${(filter===x||x==='Semua'&&['Terverifikasi','Menunggu Verifikasi','Perlu Perbaikan','Draft'].includes(filter))?'active':''}" data-record-type="${x}">${x}</button>`).join('')}</div>${recordTable(filtered)}`}
function recordDetail(r){return `<div class="actions" style="margin-bottom:14px"><button class="btn btn-sm" data-action="back-records">Kembali ke daftar</button></div><div class="split grid"><section class="card detail-card"><div class="detail-top"><div class="detail-file">PDF</div><div style="flex:1"><div class="eyebrow"><span class="record-code">${esc(r.id)}</span><span class="meta-context">${esc(r.kind)}</span></div><h2 class="detail-title">${esc(r.title)}</h2><p class="detail-intro">${esc(r.desc)}</p><div style="margin-top:10px">${badge(r.status)} <span class="sim-label">${esc(r.access)}</span></div></div></div><div class="tabs" style="margin-top:22px"><button class="tab active">Ringkasan</button><button class="tab">Metadata</button><button class="tab">Riwayat</button></div><div class="meta-grid">${[['Unit pencipta',r.unit],['Kategori',r.kind],['Tahun',r.year],['Tanggal dokumen',r.date],['Kegiatan terkait',r.activity],['Tingkat akses',r.access],['Format & ukuran',`${r.file}, ${r.size}`],['Tanggal unggah',r.date]].map(([a,b])=>`<div class="meta-item"><label>${a}</label><strong>${esc(b)}</strong></div>`).join('')}</div><h3 class="section-label">Konteks kegiatan</h3><p class="detail-intro">Dokumen ini terkait dengan <strong>${esc(r.activity)}</strong>. Pencarian berdasarkan kegiatan membantu menemukan dokumen pendukung dan pengetahuan yang saling terhubung.</p><h3 class="section-label">Arsip fisik terkait</h3>${db.physical.filter(p=>p.digital===r.id).map(p=>`<div class="related"><span class="quick-ico">▣</span><div style="flex:1"><strong style="font-size:12px">${esc(p.title)}</strong><div class="mini-meta">${esc(p.room)}, <span>${esc(p.shelf)}</span><span>${esc(p.box)}</span></div></div>${badge(p.status)}</div>`).join('')||`<div class="text-muted" style="font-size:11px">Tidak ada arsip fisik yang ditautkan.</div>`}<h3 class="section-label">Pengetahuan terkait</h3>${db.knowledge.filter(k=>k.related===r.title||k.related===r.activity).map(k=>`<div class="related" data-knowledge="${k.id}"><span class="quick-ico">✦</span><div style="flex:1"><strong style="font-size:12px">${esc(k.title)}</strong><div class="mini-meta">${esc(k.category)}, ${esc(k.unit)}</div></div></div>`).join('')||`<div class="text-muted" style="font-size:11px">Belum ada pengetahuan terkait.</div>`}</section><aside class="card detail-card"><h3 class="card-title">Tindakan</h3><p class="detail-intro" style="margin-top:8px">Aksi tersedia mengikuti peran dan status arsip.</p><div class="grid" style="margin-top:18px">${r.status==='Terverifikasi'?`<button class="btn btn-primary" data-action="download" data-id="${r.id}">Buka dokumen contoh</button>`:''}${r.status==='Draft'?`<button class="btn btn-primary" data-action="submit-record" data-id="${r.id}">Ajukan verifikasi</button>`:''}<button class="btn" data-action="copy-link" data-id="${r.id}">Salin tautan internal</button></div><h3 class="section-label">Riwayat proses</h3><div class="timeline">${(r.history||[{text:r.status==='Terverifikasi'?'Arsip diverifikasi':'Arsip dibuat',by:r.unit,time:r.date,icon:'•'}]).map(a=>`<div class="time-item"><span class="time-dot">${esc(a.icon||'•')}</span><div class="time-copy"><strong>${esc(a.text)}</strong><p><span>${esc(a.by)}</span><time>${esc(a.time)}</time></p>${a.note?`<p>Catatan: ${esc(a.note)}</p>`:''}</div></div>`).join('')}</div><div class="notice" style="margin-top:20px"><span class="notice-dot" style="background:var(--blue)"></span><div><strong>Informasi akses</strong><p>Konten hanya ditampilkan sesuai peran, unit, dan tingkat akses.</p></div></div></aside></div>`}
function verify(){let list=db.records.filter(r=>['Menunggu Verifikasi','Perlu Perbaikan'].includes(r.status));const visible = paginateQueue(list.filter(r => !query || Object.values(r).join(' ').toLowerCase().includes(query.toLowerCase())), 'verify', 5);
return `<div class="toolbar"><div class="field-search"><span>⌕</span><input id="verifySearch" placeholder="Cari arsip dalam antrean…" value="${esc(query)}"></div><span class="sim-label">${list.length} arsip perlu ditinjau</span></div>${!isVerifier()?`<div class="card empty"><div class="empty-icon">⌑</div><strong>Menu pemeriksaan untuk arsiparis</strong><div>Masuk dengan akun Arsiparis untuk melihat antrean verifikasi.</div></div>`:visible.items.length?`<div class="card table-wrap"><table class="table"><thead><tr><th>Judul arsip</th><th>Unit</th><th>Metadata</th><th>Status</th><th>Aksi pemeriksaan</th></tr></thead><tbody>${visible.items.map(r=>`<tr><td><div class="table-title">${esc(r.title)}</div><div class="table-sub"><span class="record-code">${esc(r.id)}</span><span class="meta-context">${esc(r.file)}</span></div></td><td>${esc(r.unit)}</td><td>${esc(r.kind)}, ${esc(r.year)}, ${esc(r.access)}</td><td>${badge(r.status)}</td><td><div class="actions"><button class="btn btn-sm" data-action="open-review" data-id="${r.id}">Periksa</button><button class="btn btn-sm btn-primary" data-action="approve-record" data-id="${r.id}">Setujui</button><button class="btn btn-sm btn-danger" data-action="return-record" data-id="${r.id}">Minta perbaikan</button></div></td></tr>`).join('')}</tbody></table></div>${visible.controls}`:`<div class="card empty"><div class="empty-icon">✓</div><strong>Antrean verifikasi kosong</strong><div>Arsip yang diajukan akan muncul di sini.</div></div>`}`}
function knowledge(){let list=db.knowledge.filter(k=>(filter==='Semua'||k.category===filter)&&(!query||Object.values(k).join(' ').toLowerCase().includes(query.toLowerCase())));if(selected){const k=db.knowledge.find(x=>x.id===selected);if(k)return knowledgeDetail(k)}return `<div class="toolbar"><div class="field-search"><span>⌕</span><input id="knSearch" placeholder="Cari SOP, praktik baik, sejarah…" value="${esc(query)}"></div><select id="knFilter" class="select"><option>Semua</option>${[...new Set(db.knowledge.map(k=>k.category))].map(c=>`<option ${filter===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="sim-label">${list.length} kontribusi</span></div><div class="knowledge-grid grid">${list.map(k=>`<article class="card knowledge-card" data-knowledge="${k.id}"><div style="display:flex;justify-content:space-between;align-items:center">${badge(k.category)}${k.status!=='Dipublikasikan'?badge(k.status):''}</div><h3>${esc(k.title)}</h3><p>${esc(k.summary)}</p><div class="knowledge-foot"><span class="location"><span>${esc(k.unit)}</span><time>${esc(k.year)}</time></span><button class="card-link" data-knowledge="${k.id}">Baca</button></div></article>`).join('')||`<div class="card empty">Belum ada pengetahuan yang cocok.</div>`}</div>`}
function knowledgeDetail(k){return `<button class="btn btn-sm" data-action="back-knowledge" style="margin-bottom:14px">Kembali ke pengetahuan</button><div class="split grid"><article class="card detail-card"><span>${badge(k.category)} ${badge(k.status)}</span><h2 class="detail-title" style="margin-top:14px">${esc(k.title)}</h2><p class="detail-intro">${esc(k.summary)}</p><div class="meta-grid">${[['Unit terkait',k.unit],['Periode',k.year],['Kontributor',k.author],['Status',k.status]].map(([a,b])=>`<div class="meta-item"><label>${a}</label><strong>${esc(b)}</strong></div>`).join('')}</div><h3 class="section-label">Ringkasan pengetahuan</h3><p class="detail-intro">Materi ini disimpan sebagai referensi agar proses, pengalaman, dan pembelajaran di lingkungan Sekolah Vokasi dapat ditemukan kembali dan digunakan oleh unit yang membutuhkan.</p><h3 class="section-label">Dokumen pendukung</h3>${k.related?`<div class="related" data-record="${(db.records.find(r=>r.title===k.related)||{}).id||''}">${iconBox()}<div><strong style="font-size:12px">${esc(k.related)}</strong><div class="mini-meta">Arsip digital terkait</div></div></div>`:`<p class="text-muted" style="font-size:11px">Belum ada dokumen pendukung yang ditautkan.</p>`}</article><aside class="card detail-card"><h3 class="card-title">Informasi kontribusi</h3><div class="meta-grid" style="grid-template-columns:1fr">${[['Kontributor',k.author],['Unit',k.unit],['Tahun',k.year],['Kata kunci',(k.tags||[]).join(', ')]].map(([a,b])=>`<div class="meta-item"><label>${a}</label><strong>${esc(b)}</strong></div>`).join('')}</div>${k.status==='Menunggu Review'&&isVerifier()?`<button class="btn btn-primary" data-action="approve-knowledge" data-id="${k.id}">✓ Publikasikan</button>`:''}</aside></div>`}
function recordcenter(){let list=db.physical.filter(p=>(filter==='Semua'||p.status===filter)&&(!query||Object.values(p).join(' ').toLowerCase().includes(query.toLowerCase())));let requests=db.requests;return `<div class="stat-grid grid" style="grid-template-columns:repeat(3,1fr)">${[['Arsip terinventaris',db.physical.length,'▣'],['Tersedia',db.physical.filter(p=>p.status==='Tersedia').length,'✓'],['Menunggu persetujuan',requests.filter(r=>r.status==='Menunggu Persetujuan').length,'◷']].map(([a,b,c])=>`<div class="card stat"><div class="stat-top">${a}<span class="stat-icon">${c}</span></div><div class="stat-num">${String(b).padStart(2,'0')}</div></div>`).join('')}</div><div class="tabs"><button class="tab ${filter==='Semua'||filter==='Tersedia'||filter==='Dipinjam'?'active':''}" data-rc-tab="inventaris">Arsip fisik</button><button class="tab" data-rc-tab="permohonan">Permohonan & sirkulasi</button></div>${filter==='Permohonan'?`<div class="card table-wrap"><table class="table"><thead><tr><th>Arsip</th><th>Peminjam</th><th>Tujuan</th><th>Rencana kembali</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${requests.map(r=>`<tr><td><div class="table-title">${esc(r.record)}</div><div class="table-sub">${esc(r.id)}</div></td><td>${esc(r.applicant)}<div class="table-sub">${esc(r.unit)}</div></td><td>${esc(r.purpose)}</td><td>${esc(r.due)}</td><td>${badge(r.status)}</td><td>${r.status==='Menunggu Persetujuan'&&isVerifier()?`<button class="btn btn-sm btn-primary" data-action="approve-loan" data-id="${r.id}">Tinjau</button>`:r.status==='Disetujui'&&isVerifier()?`<button class="btn btn-sm" data-action="handover" data-id="${r.id}">Catat serah terima</button>`:r.status==='Dipinjam'&&isVerifier()?`<button class="btn btn-sm" data-action="return-loan" data-id="${r.id}">Catat pengembalian</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:`<div class="toolbar"><div class="field-search"><span>⌕</span><input id="physSearch" placeholder="Cari arsip, unit, kode, lokasi…" value="${esc(query)}"></div><select id="physFilter" class="select">${['Semua','Tersedia','Dipinjam'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn btn-primary" data-action="new-physical">＋ Catat arsip fisik</button></div><div class="card table-wrap"><table class="table"><thead><tr><th>Judul / kode inventaris</th><th>Prodi / Unit</th><th>Kurun waktu</th><th>Lokasi penyimpanan</th><th>Kondisi</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${list.map(p=>`<tr><td><div class="table-title">${esc(p.title)}</div><div class="table-sub">${esc(p.code)}</div></td><td>${esc(p.unit)}</td><td>${esc(p.year)}</td><td><div>${esc(p.room)}</div><div class="table-sub"><span>${esc(p.shelf)}</span><span>${esc(p.box)}</span></div></td><td>${esc(p.condition)}</td><td>${badge(p.status)}</td><td><button class="btn btn-sm" data-physical="${p.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`}`}
function physicalDetail(p){return `<div class="modal-backdrop" data-close><section class="modal"><header class="modal-head"><div><h2>${esc(p.title)}</h2><p><span class="record-code">${esc(p.code)}</span> ${badge(p.status)}</p></div><button class="modal-close" data-close>×</button></header><div class="modal-body"><div class="meta-grid">${[['Unit pencipta',p.unit],['Kurun waktu',p.year],['Ruang',p.room],['Rak',p.shelf],['Boks',p.box],['Kondisi',p.condition]].map(([a,b])=>`<div class="meta-item"><label>${a}</label><strong>${esc(b)}</strong></div>`).join('')}</div>${p.digital?`<div class="related" data-record="${p.digital}">${iconBox()}<div><strong style="font-size:12px">Metadata digital terkait</strong><div class="mini-meta">${esc(p.digital)}</div></div></div>`:''}</div><footer class="modal-foot"><button class="btn" data-close>Tutup</button>${p.status==='Tersedia'?`<button class="btn btn-primary" data-action="request-loan" data-id="${p.id}">Ajukan peminjaman</button>`:''}</footer></section></div>`}
function search(){let q=query.toLowerCase();let rec=(canOpenPage('records') ? db.records : []).filter(r=>r.status==='Terverifikasi'&&(!q||Object.values(r).join(' ').toLowerCase().includes(q)));let phys=(canOpenPage('recordcenter') ? db.physical : []).filter(p=>!q||Object.values(p).join(' ').toLowerCase().includes(q));let know=db.knowledge.filter(k=>k.status==='Dipublikasikan'&&(!q||Object.values(k).join(' ').toLowerCase().includes(q)));let all=[...rec.map(x=>({...x,source:'Arsip digital'})),...phys.map(x=>({...x,source:'Arsip fisik'})),...know.map(x=>({...x,source:'Pengetahuan'}))].filter(x=>searchMode==='Semua'||x.source===searchMode);return `<div class="toolbar"><div class="field-search" style="max-width:none"><span>⌕</span><input id="searchPage" placeholder="Masukkan nama kegiatan, dokumen, unit…" value="${esc(query)}"></div><button class="btn btn-primary" data-action="search">Cari</button></div><div class="toolbar" style="justify-content:space-between"><div class="segmented">${['Semua','Arsip digital','Arsip fisik','Pengetahuan'].map(x=>`<button data-search-mode="${x}" class="${searchMode===x?'active':''}">${x}</button>`).join('')}</div><span class="sim-label">${all.length} hasil</span></div><div class="search-results">${all.map(x=>`<article class="card result" data-${x.source==='Arsip fisik'?'physical':x.source==='Pengetahuan'?'knowledge':'record'}="${x.id}">${iconBox(x.source==='Pengetahuan'?'KN':x.source==='Arsip fisik'?'FIS':'PDF')}<div class="result-main"><span class="eyebrow">${esc(x.source)}</span><h3>${esc(x.title)}</h3><p>${esc(x.summary||x.desc||x.activity||'Arsip fisik dalam inventaris Record Center.')}</p><div class="result-meta"><span>${esc(x.unit)}</span><time>${esc(x.year)}</time>${x.status?`<span>${badge(x.status)}</span>`:''}${x.room?`<span>${esc(x.room)}, ${esc(x.shelf)}, ${esc(x.box)}</span>`:''}${x.activity?`<span>Kegiatan: ${esc(x.activity)}</span>`:''}</div></div></article>`).join('')||`<div class="card empty"><div class="empty-icon">⌕</div><strong>Belum ada hasil</strong><div>Coba kata kunci lain seperti “seminar”, “arsip”, atau nama unit.</div></div>`}</div>`}
const classificationFields = {
  kind: 'Kategori arsip', unit: 'Unit / Prodi', year: 'Tahun', activity: 'Topik / Kegiatan'
};
let classificationField = 'kind';
let classificationValue = '';

function classification() {
  const records = db.records.filter(record => record.status === 'Terverifikasi' &&
    (record.access === 'Internal' ? role !== 'Mahasiswa' : role === 'Arsiparis' && record.access === 'Unit terkait'));
  const options = [...new Set(records.map(record => record[classificationField]).filter(Boolean))].sort();
  const matches = records.filter(record => !classificationValue || record[classificationField] === classificationValue);
  return `<div class="toolbar">
    <select id="classificationField" class="select" aria-label="Kelompok klasifikasi">${Object.entries(classificationFields).map(([key,label]) => `<option value="${key}" ${key === classificationField ? 'selected' : ''}>${label}</option>`).join('')}</select>
    <select id="classificationValue" class="select" aria-label="Nilai klasifikasi"><option value="">Semua</option>${options.map(value => `<option ${value === classificationValue ? 'selected' : ''}>${esc(value)}</option>`).join('')}</select>
  </div>${recordTable(matches)}`;
}

function reports() {
  const sources = [
    ['Arsip digital', db.records],
    ['Arsip fisik', db.physical],
    ['Pengetahuan', db.knowledge],
    ['Peminjaman', db.requests]
  ];
  return `<div class="grid stat-grid">${sources.map(([label, items]) =>
    `<section class="card stat"><div class="stat-top">${label}</div><div class="stat-num">${items.length}</div></section>`).join('')}</div>
    <div class="grid split">${sources.map(([label, items]) => {
      const counts = Map.groupBy(items, item => item.status);
      return `<section class="card section-card"><h2 class="card-title">${label} menurut status</h2>
        ${[...counts].map(([status, group]) => `<div class="mini-row"><div class="mini-main">${badge(status)}</div><strong>${group.length}</strong></div>`).join('') || '<p>Belum ada data.</p>'}
      </section>`;
    }).join('')}</div>`;
}

const pages={dashboard,records,verify,knowledge,recordcenter,search,classification,reports};
const demoAccounts = new Map([
  ['arsiparis', 'Arsiparis'], ['admin-unit', 'Admin Prodi/Unit'],
  ['pimpinan', 'Pimpinan'], ['dosen', 'Dosen'], ['tendik', 'Tendik'],
  ['mahasiswa', 'Mahasiswa']
]);

function render(){
  if(sessionStorage.getItem('langgeng-session')) return layout();
  $('#app').innerHTML=`<main class="login"><section class="login-panel"><div class="brand"><div class="brand-mark">L</div><div><div class="brand-name">LANGGENG</div><div class="brand-sub">Institutional Memory System</div></div></div><h1>Masuk ke LANGGENG</h1><p>Sekolah Vokasi Universitas Padjadjaran</p><form id="loginForm"><label for="loginUsername">Username</label><input id="loginUsername" autocomplete="username" required><button class="btn btn-primary" type="submit">Masuk</button></form></section></main>`;
  $('#loginForm').onsubmit = event => {
    event.preventDefault();
    const chosenRole = demoAccounts.get($('#loginUsername').value.trim().toLowerCase());
    
    const error = {hidden:true};
    error.hidden = true;
    act(event.submitter, () => {
      if (!chosenRole) {
        toast('Username demo tidak ditemukan.', true);
        error.hidden = false;
        return;
      }
      role = chosenRole;
      localStorage.setItem('langgeng-role', role);
      sessionStorage.setItem('langgeng-session', 'active');
      render();
    }, 'Masuk…');
  };
}
const roleMenus = {
  'Admin Prodi/Unit': ['records','knowledge','recordcenter','classification'],
  'Arsiparis': ['records','verify','knowledge','recordcenter','classification','reports'],
  'Pimpinan': ['records','knowledge','recordcenter','classification','reports'],
  'Dosen': ['records','knowledge','recordcenter','classification'],
  'Tendik': ['records','knowledge','recordcenter','classification'],
  'Mahasiswa': ['knowledge']
};
function canOpenPage(name) {
  return name === 'dashboard' || name === 'search' || (roleMenus[role] || []).includes(name);
}
const actionRoles = {
  'new-record': ['Admin Prodi/Unit'],
  'submit-record': ['Admin Prodi/Unit'],
  'new-knowledge': ['Admin Prodi/Unit','Dosen','Tendik'],
  'new-physical': ['Arsiparis'],
  'request-loan': ['Dosen','Tendik'],
  'approve-record': ['Arsiparis'], 'return-record': ['Arsiparis'],
  'approve-knowledge': ['Arsiparis'], 'open-review': ['Arsiparis'],
  'approve-loan': ['Arsiparis'], 'handover': ['Arsiparis'], 'return-loan': ['Arsiparis']
};
function permits(actionName) {
  return !actionRoles[actionName] || actionRoles[actionName].includes(role);
}
function bind(){
  $$("[data-page]").filter(button => !canOpenPage(button.dataset.page)).forEach(button => button.remove());
  $$('[data-action]').filter(button => !permits(button.dataset.action)).forEach(button => button.remove());

  const fieldSelector = $('#classificationField');
  if (fieldSelector) fieldSelector.onchange = () => {
    classificationField = fieldSelector.value;
    classificationValue = '';
    render();
  };
  const valueSelector = $('#classificationValue');
  if (valueSelector) valueSelector.onchange = () => {
    classificationValue = valueSelector.value;
    render();
  };

$$('[data-page]').forEach(b=>{if(b.closest('.content')||b.classList.contains('quick'))b.onclick=()=>{page=b.dataset.page;selected=null;query='';render()}});
$$('[data-action]').forEach(b=>b.onclick=()=>act(b,()=>action(b.dataset.action,b.dataset.id,b),b.dataset.action==='search'?'Mencari…':'Memproses…'));
$$('[data-record]').forEach(b=>b.onclick=()=>{selected=b.dataset.record;page='records';render()});$$('[data-knowledge]').forEach(b=>b.onclick=()=>{selected=b.dataset.knowledge;page='knowledge';render()});$$('[data-physical]').forEach(b=>b.onclick=()=>{let p=db.physical.find(x=>x.id===b.dataset.physical);modal=physicalDetail(p);renderModal()});
for(const [id,key]of [['recSearch','record'],['verifySearch','verify'],['knSearch','knowledge'],['physSearch','recordcenter']]){let e=$('#'+id);if(e)e.oninput=()=>{query=e.value;if(id==='verifySearch')queuePages.verify=1;let pos=e.selectionStart;render();let next=$('#'+id);next?.focus();next?.setSelectionRange(pos,pos)}}
for(const id of ['recFilter','knFilter','physFilter']){let e=$('#'+id);if(e)e.onchange=()=>{filter=e.value;render()}}
$$('[data-record-type]').forEach(b=>b.onclick=()=>{filter=b.dataset.recordType==='Semua'?'Semua':b.dataset.recordType==='Digital'?'Terverifikasi':'Semua';query='';render()});$$('[data-rc-tab]').forEach(b=>b.onclick=()=>{filter=b.dataset.rcTab==='permohonan'?'Permohonan':'Tersedia';render()});$$('[data-search-mode]').forEach(b=>b.onclick=()=>{searchMode=b.dataset.searchMode;render()});let sq=$('#searchPage');if(sq)sq.oninput=()=>{query=sq.value};
$$('[data-close]').forEach(b=>b.onclick=e=>{if(e.target===b||b.matches('button')){modal=null;render()}});
}
function renderModal(){let old=$('.modal-backdrop');if(old)old.remove();if(!modal)return;document.body.insertAdjacentHTML('beforeend',modal);bind()}
function field(label,name,opts={}){let input=opts.options?`<select name="${name}" ${opts.required?'required':''}><option value="">Pilih ${label.toLowerCase()}</option>${opts.options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`:opts.area?`<textarea name="${name}" ${opts.required?'required':''} placeholder="${esc(opts.placeholder||'Tulis '+label.toLowerCase())}"></textarea>`:`<input name="${name}" type="${opts.type||'text'}" ${opts.required?'required':''} placeholder="${esc(opts.placeholder||'Masukkan '+label.toLowerCase())}" ${opts.value?`value="${esc(opts.value)}"`:''}>`;return `<div class="form-field ${opts.full?'full':''}"><label>${label}${opts.required?' <em>*</em>':''}</label>${input}${opts.hint?`<small class="form-hint">${opts.hint}</small>`:''}</div>`}
function openForm(type,id){let isK=type==='knowledge',isP=type==='physical',r=id?db.records.find(x=>x.id===id):null;let title=type==='record'?(r?'Perbaiki arsip':'Tambah arsip digital'):isK?'Tambah pengetahuan kelembagaan':isP?'Catat arsip fisik':type==='loan'?'Ajukan peminjaman arsip fisik':'Tinjau permohonan';let fields=type==='record'?`<div class="form-section"><h3>Informasi arsip</h3><div class="form-grid">${field('Judul arsip','title',{required:true,value:r?.title})}${field('Kategori / jenis','kind',{required:true,options:['Surat','Surat Keputusan','Laporan','Laporan Kegiatan','Pedoman','Notula','Berita Acara','Dokumen Akademik']})}${field('Unit pencipta','unit',{required:true,options:UNITS})}${field('Tahun','year',{required:true,type:'number',value:r?.year||'2026'})}${field('Tanggal dokumen','date',{type:'date',value:r?.date})}${field('Kegiatan terkait','activity',{placeholder:'Contoh: Seminar Vokasi 2026'})}${field('Deskripsi / ringkasan','desc',{area:true,full:true,value:r?.desc})}</div></div><div class="form-section"><h3>Berkas dan akses</h3><div class="form-grid"><div class="form-field full"><label>Berkas digital <em>*</em></label><label class="upload-box"><input id="filePick" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.jpg,.png"><strong id="fileName">Pilih berkas atau jatuhkan di sini</strong><small>PDF, dokumen Office, JPG, atau PNG</small></label></div>${field('Tingkat akses','access',{required:true,options:['Internal','Unit terkait','Terbatas']})}${field('Unit yang boleh mengakses','shared',{options:UNITS,hint:'Pilihan akhir mengikuti kebijakan pengelola.'})}</div></div>`:isK?`<div class="form-section"><h3>Informasi pengetahuan</h3><div class="form-grid">${field('Judul pengetahuan','title',{required:true})}${field('Kategori','category',{required:true,options:['SOP & Pedoman','Praktik Baik','Sejarah Kelembagaan','Pengalaman & Pembelajaran','FAQ','Dokumentasi Kegiatan']})}${field('Unit terkait','unit',{required:true,options:UNITS})}${field('Tahun / periode','year',{type:'number',value:'2026'})}${field('Kontributor / narasumber','author',{placeholder:'Nama atau jabatan'})}${field('Dokumen pendukung','related',{options:db.records.map(r=>r.title)})}${field('Ringkasan','summary',{required:true,area:true,full:true})}${field('Pembelajaran / manfaat','lesson',{area:true,full:true})}</div></div>`:isP?`<div class="form-section"><h3>Identitas dan lokasi arsip</h3><div class="form-grid">${field('Judul / uraian arsip','title',{required:true})}${field('Kode inventaris','code',{required:true})}${field('Unit pencipta','unit',{required:true,options:UNITS})}${field('Tahun / kurun waktu','year',{required:true})}${field('Ruang','room',{required:true,placeholder:'Record Center, Ruang 204'})}${field('Rak','shelf',{required:true})}${field('Nomor boks','box',{required:true})}${field('Kondisi fisik','condition',{options:['Baik','Perlu penanganan']})}${field('Arsip digital terkait','digital',{options:db.records.map(r=>r.id)})}</div></div>`:type==='loan'?`<div class="form-section"><h3>Permohonan peminjaman</h3><div class="form-grid">${field('Arsip','recordTitle',{required:true,value:db.physical.find(p=>p.id===id)?.title})}${field('Nama peminjam','applicant',{required:true,value:role==='Dosen'?'Dr. Rani Prameswari':'Arif Nugraha'})}${field('Unit','unit',{required:true,options:UNITS})}${field('Tujuan peminjaman','purpose',{required:true,area:true,full:true})}${field('Tanggal dibutuhkan','need',{required:true,type:'date'})}${field('Rencana pengembalian','due',{required:true,type:'date'})}</div></div>`:`<div class="form-section"><h3>Tinjau permohonan</h3><p class="detail-intro">Periksa tujuan dan tanggal permohonan. Keputusan dicatat pada riwayat.</p><div class="form-grid">${field('Keputusan','decision',{required:true,options:['Setujui','Tolak']})}${field('Alasan / catatan','note',{area:true,full:true})}</div></div>`;let foot=type==='record'?`<button class="btn" data-action="save-draft">Simpan draf</button><button class="btn btn-primary" data-action="submit-record-form">Kirim verifikasi</button>`:type==='knowledge'?`<button class="btn" data-action="save-knowledge-draft">Simpan draf</button><button class="btn btn-primary" data-action="submit-knowledge">Kirim untuk review</button>`:type==='physical'?`<button class="btn" data-action="cancel-modal">Batal</button><button class="btn btn-primary" data-action="save-physical">Simpan inventaris</button>`:type==='loan'?`<button class="btn" data-action="cancel-modal">Batal</button><button class="btn btn-primary" data-action="send-loan">Ajukan peminjaman</button>`:`<button class="btn" data-action="cancel-modal">Tutup</button><button class="btn btn-primary" data-action="decide-loan">Simpan keputusan</button>`;modal=`<div class="modal-backdrop" data-close><section class="modal"><header class="modal-head"><div><h2>${title}</h2><p>Lengkapi kolom yang diperlukan.</p></div><button class="modal-close" data-close>×</button></header><form id="modalForm"><div class="modal-body">${fields}</div><footer class="modal-foot">${foot}</footer></form></section></div>`;renderModal();let fp=$('#filePick');if(fp)fp.onchange=()=>{$('#fileName').textContent=fp.files?.[0]?.name||'Pilih berkas atau jatuhkan di sini'};$$('#modalForm [data-action]').forEach(b=>b.onclick=e=>{e.preventDefault();act(b,()=>formAction(b.dataset.action,type,id),b.textContent.includes('draf')?'Menyimpan draf…':'Mengirim…')})}
function formData(){let f=$('#modalForm');if(!f.reportValidity())throw Error('Mohon lengkapi semua kolom wajib.');return Object.fromEntries(new FormData(f).entries())}
function closeModal(){modal=null;$('.modal-backdrop')?.remove();render()}
function action(a,id,b){
  if (!permits(a)) return;

  if (a === 'queue-page') {
    queuePages[id] += Number(b.dataset.step);
    return render();
  }

  if (a === 'open-unit-queue' && isVerifier()) {
    page = 'verify';
    selected = null;
    query = id;
    queuePages.verify = 1;
    return render();
  }

  if(a==='logout'){
    sessionStorage.removeItem('langgeng-session');
    page='dashboard';
    selected=null;
    query='';
    filter='Semua';
    return render();
  }
if(a==='new-record')return openForm('record');if(a==='new-knowledge')return openForm('knowledge');if(a==='new-physical')return openForm('physical');if(a==='cancel-modal')return closeModal();if(a==='back-records'){selected=null;query='';return render()}if(a==='back-knowledge'){selected=null;return render()}if(a==='submit-record')return submitRecord(id);if(a==='approve-record'||a==='return-record')return decideRecord(id,a);if(a==='open-review'){selected=id;page='records';render();return toast('Periksa metadata, unit, kategori, dan tingkat akses arsip.')}if(a==='download')return toast('Pratinjau berkas belum tersedia.');if(a==='copy-link')return toast('Tautan internal belum tersedia.');if(a==='request-loan')return openForm('loan',id);if(a==='approve-loan')return openForm('decision',id);if(a==='handover')return handover(id);if(a==='return-loan')return returnLoan(id);if(a==='approve-knowledge')return approveKnowledge(id);if(a==='search'){query=$('#searchPage')?.value||query;page='search';return render()}if(a==='save-draft'||a==='submit-record-form'||a==='save-knowledge-draft'||a==='submit-knowledge'||a==='save-physical'||a==='send-loan'||a==='decide-loan')return formAction(a,modal?.includes('Ajukan peminjaman')?'loan':modal?.includes('Tinjau permohonan')?'decision':modal?.includes('Catat arsip fisik')?'physical':modal?.includes('pengetahuan')?'knowledge':'record',id)}
function activity(text,by=role){db.activities.unshift({text,by,time:'Baru saja',icon:'•'});db.activities=db.activities.slice(0,12)}
function submitRecord(id){let r=db.records.find(x=>x.id===id);if(!r)return; r.status='Menunggu Verifikasi';r.history=[...(r.history||[]),{text:'Diajukan untuk verifikasi',by:role,time:'Baru saja',icon:'•'}];activity(`${r.title} diajukan untuk verifikasi`);save();selected=null;toast('Arsip dikirim ke antrean verifikasi.');render()}
function decideRecord(id,act){let r=db.records.find(x=>x.id===id);if(!r)return;let note=prompt(act==='approve-record'?'Catatan pemeriksaan (opsional):':'Catatan perbaikan yang perlu dilakukan:')||'';if(act==='return-record'&&!note.trim())return toast('Tuliskan catatan agar pengunggah mengetahui perbaikannya.',true);r.status=act==='approve-record'?'Terverifikasi':'Perlu Perbaikan';r.history=[...(r.history||[]),{text:act==='approve-record'?'Arsip disetujui dan diverifikasi':'Arsip dikembalikan untuk perbaikan',by:role,time:'Baru saja',icon:act==='approve-record'?'✓':'•',note}];activity(`${r.title} ${act==='approve-record'?'diverifikasi':'dikembalikan untuk perbaikan'}`);save();toast(act==='approve-record'?'Arsip berhasil diverifikasi.':'Arsip dikembalikan dengan catatan.');render()}
function approveKnowledge(id){let k=db.knowledge.find(x=>x.id===id);if(!k)return;k.status='Dipublikasikan';activity(`${k.title} dipublikasikan`);save();toast('Kontribusi pengetahuan dipublikasikan.');render()}
function handover(id){let r=db.requests.find(x=>x.id===id);if(!r)return;let c=prompt('Kondisi arsip saat diserahkan:','Baik');if(c===null)return;r.status='Dipinjam';r.conditionOut=c;let p=db.physical.find(x=>x.title===r.record);if(p)p.status='Dipinjam';activity(`Arsip fisik diserahkan kepada ${r.applicant}`);save();toast('Serah terima berhasil dicatat.');render()}
function returnLoan(id){let r=db.requests.find(x=>x.id===id);if(!r)return;let c=prompt('Kondisi arsip saat dikembalikan:','Baik');if(c===null)return;r.status='Dikembalikan';r.conditionIn=c;let p=db.physical.find(x=>x.title===r.record);if(p)p.status='Tersedia';activity(`Arsip dikembalikan oleh ${r.applicant}`);save();toast('Pengembalian berhasil dicatat.');render()}
function formAction(a,type,id){if(a==='cancel-modal')return closeModal();let d=formData();if(type==='record'){if(a==='save-draft'){db.records.unshift({id:`LG-2026-${String(49+db.records.length).padStart(4,'0')}`,title:d.title,kind:d.kind,unit:d.unit,year:d.year,date:d.date||new Date().toISOString().slice(0,10),activity:d.activity||'Tidak ditautkan',access:d.access||'Internal',status:'Draft',desc:d.desc||'',file:$('#filePick')?.files?.[0]?.name||'Dokumen-contoh.pdf',size:'—',type:'Digital',tags:[]});activity('Draf arsip baru disimpan')}else if(a==='submit-record-form'){let f=$('#filePick');if(!f?.files?.length&&!id)throw Error('Pilih berkas contoh terlebih dahulu.');let obj={id:`LG-2026-${String(49+db.records.length).padStart(4,'0')}`,title:d.title,kind:d.kind,unit:d.unit,year:d.year,date:d.date||new Date().toISOString().slice(0,10),activity:d.activity||'Tidak ditautkan',access:d.access||'Internal',status:'Menunggu Verifikasi',desc:d.desc||'',file:f?.files?.[0]?.name||'Dokumen-contoh.pdf',size:f?.files?.[0]?`${(f.files[0].size/1024/1024).toFixed(1)} MB`:'—',type:'Digital',tags:[],history:[{text:'Diajukan untuk verifikasi',by:role,time:'Baru saja',icon:'•'}]};db.records.unshift(obj);activity(`${obj.title} diajukan untuk verifikasi`)}save();toast(a==='save-draft'?'Draf arsip tersimpan.':'Arsip diajukan untuk verifikasi.');return closeModal()}
if(type==='knowledge'){if(a==='save-knowledge-draft'||a==='submit-knowledge'){let k={id:`KN-${String(15+db.knowledge.length).padStart(3,'0')}`,title:d.title,category:d.category,unit:d.unit,year:d.year,summary:d.summary,status:a==='submit-knowledge'?'Menunggu Review':'Draft',author:d.author||role,related:d.related||'',tags:[]};db.knowledge.unshift(k);activity(`${k.title} ${a==='submit-knowledge'?'dikirim untuk review':'disimpan sebagai draf'}`);save();toast(a==='submit-knowledge'?'Kontribusi dikirim untuk review.':'Draf pengetahuan tersimpan.');return closeModal()}}
if(type==='physical'){let p={id:`RC-${String(32+db.physical.length).padStart(4,'0')}`,title:d.title,unit:d.unit,year:d.year,code:d.code,room:d.room,shelf:d.shelf,box:d.box,condition:d.condition||'Baik',status:'Tersedia',digital:d.digital||''};db.physical.unshift(p);activity(`${p.title} dicatat pada inventaris fisik`);save();toast('Inventaris arsip fisik tersimpan.');return closeModal()}
if(type==='loan'){let p=db.physical.find(x=>x.id===id);if(!p||p.status!=='Tersedia')throw Error('Arsip ini tidak tersedia untuk dipinjam.');let req={id:`PJ-${String(9+db.requests.length).padStart(3,'0')}`,record:p.title,applicant:d.applicant,unit:d.unit,purpose:d.purpose,need:d.need,due:d.due,status:'Menunggu Persetujuan',conditionOut:''};db.requests.unshift(req);activity(`Permohonan peminjaman ${p.title} diajukan`,req.applicant);save();toast('Permohonan dikirim kepada arsiparis.');return closeModal()}
if(type==='decision'){let r=db.requests.find(x=>x.id===id);if(!r)return;r.status=d.decision==='Setujui'?'Disetujui':'Ditolak';r.decisionNote=d.note;activity(`Permohonan ${r.id} ${r.status.toLowerCase()}`);save();toast(`Permohonan ${r.status.toLowerCase()}.`);return closeModal()}}
// Per-entry approve / return controls shown on pending record rows through detail and modal.
document.addEventListener('click',e=>{let row=e.target.closest('[data-record]');if(row&&!e.target.closest('button')){selected=row.dataset.record;page='records';render()} });
render();
